 private boolean hasByte(Program p){return p.globals().stream().anyMatch(g->g.type().equals("byte"))||p.functions().stream().anyMatch(f->f.returnType().equals("byte")||f.parameters().stream().anyMatch(x->x.type().equals("byte")||x.type().equals("byte[]"))||hasByte(f.body()));} private boolean hasByte(Statement s){if(s instanceof VariableDeclaration v)return v.type().equals("byte")||v.initializer().map(this::hasByte).orElse(false);if(s instanceof ArrayDeclaration a)return a.elementType().equals("byte");if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasByte);if(s instanceof ReturnStatement r)return r.value().map(this::hasByte).orElse(false);if(s instanceof ExpressionStatement e)return hasByte(e.expression());if(s instanceof IfStatement i)return hasByte(i.thenBranch())||i.elseBranch().map(this::hasByte).orElse(false);if(s instanceof WhileStatement w)return hasByte(w.body());if(s instanceof DoWhileStatement d)return hasByte(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasByte).orElse(false)||hasByte(f.body());return false;} private boolean hasByte(Expression e){if(e instanceof BinaryExpression b)return hasByte(b.left())||hasByte(b.right());if(e instanceof CallExpression c)return c.arguments().stream().anyMatch(this::hasByte);if(e instanceof AssignmentExpression a)return hasByte(a.target())||hasByte(a.value());if(e instanceof ArrayAccessExpression a)return hasByte(a.array())||hasByte(a.index());if(e instanceof UnaryExpression u)return hasByte(u.operand());return false;} private boolean hasArray(Program p){return p.functions().stream().anyMatch(f->hasArray(f.body()));} private boolean hasArray(Statement s){if(s instanceof ArrayDeclaration)return true;if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasArray);if(s instanceof IfStatement i)return hasArray(i.thenBranch())||i.elseBranch().map(this::hasArray).orElse(false);if(s instanceof WhileStatement w)return hasArray(w.body());if(s instanceof DoWhileStatement d)return hasArray(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasArray).orElse(false)||hasArray(f.body());return false;} private boolean hasString(Program p){return p.globals().stream().anyMatch(g->g.type().equals("String")||g.type().equals("string"))||p.functions().stream().anyMatch(f->(f.returnType().equals("string")||f.returnType().equals("String"))||f.parameters().stream().anyMatch(x->(x.type().equals("string")||x.type().equals("String")))||hasString(f.body()));} private boolean hasString(Statement s){if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasString);if(s instanceof VariableDeclaration v)return (v.type().equals("string")||v.type().equals("String"))||v.initializer().map(this::hasString).orElse(false);if(s instanceof ArrayDeclaration a)return a.elementType().equals("string")||a.elementType().equals("String");if(s instanceof ReturnStatement r)return r.value().map(this::hasString).orElse(false);if(s instanceof ExpressionStatement e)return hasString(e.expression());if(s instanceof IfStatement i)return hasString(i.thenBranch())||i.elseBranch().map(this::hasString).orElse(false);if(s instanceof WhileStatement w)return hasString(w.body());if(s instanceof DoWhileStatement d)return hasString(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasString).orElse(false)||hasString(f.body());return false;} private boolean hasString(Expression e){if(e instanceof LiteralExpression l)return l.value() instanceof String;if(e instanceof BinaryExpression b)return hasString(b.left())||hasString(b.right());if(e instanceof CallExpression c)return c.arguments().stream().anyMatch(this::hasString);return false;} private boolean hasCstdio(Program p){return p.functions().stream().anyMatch(f->hasCstdio(f.body()));}
 private boolean hasCstdio(Statement s){if(s instanceof BlockStatement b)return b.statements().stream().anyMatch(this::hasCstdio);if(s instanceof VariableDeclaration v)return v.initializer().map(this::hasCstdio).orElse(false);if(s instanceof ReturnStatement r)return r.value().map(this::hasCstdio).orElse(false);if(s instanceof ExpressionStatement e)return hasCstdio(e.expression());if(s instanceof IfStatement i)return hasCstdio(i.condition())||hasCstdio(i.thenBranch())||i.elseBranch().map(this::hasCstdio).orElse(false);if(s instanceof WhileStatement w)return hasCstdio(w.condition())||hasCstdio(w.body());if(s instanceof DoWhileStatement d)return hasCstdio(d.condition())||hasCstdio(d.body());if(s instanceof ForStatement f)return f.initializer().map(this::hasCstdio).orElse(false)||f.condition().map(this::hasCstdio).orElse(false)||f.update().map(this::hasCstdio).orElse(false)||hasCstdio(f.body());if(s instanceof ArrayDeclaration a)return hasCstdio(a.size());return false;}
