 private String parameterType(String type){if(cppStyle&&type.endsWith("[]"))return "std::vector<"+typeName(type.substring(0,type.length()-2))+">&";return typeName(type);} private String typeName(String type){if(type.equals("c-long"))return "long";if(cppStyle&&type.equals("byte"))return "std::int8_t";if(cppStyle&&type.equals("long"))return "long long";if(cppStyle&&(type.equals("string")||type.equals("String")))return "std::string";if(cppStyle&&type.equals("_Bool"))return "bool";if(!cppStyle&&type.equals("bool"))return "_Bool";return type;}
 private void global(StringBuilder b,GlobalVariableDeclaration g){b.append(g.readOnly()?"const ":"static ").append(typeName(g.type())).append(" ").append(g.name());g.initializer().ifPresent(v->{b.append(" = ");expression(b,v);});b.append(";");}
 private void function(StringBuilder b,FunctionDeclaration f){b.append(typeName(f.returnType())).append(' ').append(f.name()).append('(');if(f.parameters().isEmpty()){if(!cppStyle)b.append("void");}else for(int i=0;i<f.parameters().size();i++){if(i>0)b.append(", ");Parameter p=f.parameters().get(i);b.append(parameterType(p.type())).append(' ').append(p.name());}b.append(") ");block(b,f.body(),0);b.append('\n');}
 private void block(StringBuilder b,BlockStatement x,int d){b.append("{\n");for(Statement s:x.statements()){b.append("    ".repeat(d+1));statement(b,s,d+1);b.append('\n');}b.append("    ".repeat(d)).append('}');}
 private void statement(StringBuilder b,Statement s,int d){if(s instanceof BlockStatement x)block(b,x,d);else if(s instanceof ArrayDeclaration x){if(cppStyle){b.append("std::vector<").append(typeName(x.elementType())).append("> ").append(x.name()).append('(');expression(b,x.size());b.append(");");}else{b.append(typeName(x.elementType())).append(' ').append(x.name()).append('[');expression(b,x.size());b.append("];");}}else if(s instanceof VariableDeclaration x){b.append(typeName(x.type())).append(' ').append(x.name());x.initializer().ifPresent(e->{b.append(" = ");expression(b,e);});b.append(';');}else if(s instanceof ExpressionStatement x){expression(b,x.expression());b.append(';');}else if(s instanceof ReturnStatement x){b.append("return");x.value().ifPresent(e->{b.append(' ');expression(b,e);});b.append(';');}else if(s instanceof BreakStatement)b.append("break;");else if(s instanceof ContinueStatement)b.append("continue;");else if(s instanceof ForStatement x){b.append("for (");x.initializer().ifPresent(init->forInitializer(b,init));b.append("; ");x.condition().ifPresent(e->expression(b,e));b.append("; ");x.update().ifPresent(e->expression(b,e));b.append(") ");statement(b,x.body(),d);}else if(s instanceof IfStatement x){b.append("if (");expression(b,x.condition());b.append(") ");statement(b,x.thenBranch(),d);x.elseBranch().ifPresent(branch->{b.append(" else ");statement(b,branch,d);});}else if(s instanceof DoWhileStatement x){b.append("do ");statement(b,x.body(),d);b.append(" while (");expression(b,x.condition());b.append(");");}else if(s instanceof WhileStatement x){b.append("while (");expression(b,x.condition());b.append(") ");statement(b,x.body(),d);}else throw new UnsupportedOperationException("Unsupported C statement node: "+s.getClass().getSimpleName());}
