 private void appendForDeclarator(StringBuilder b,VariableDeclaration variable){b.append(variable.name());variable.initializer().ifPresent(value->{b.append(" = ");expression(b,value);});} private String quoteString(String value){StringBuilder out=new StringBuilder("\"");for(char c:value.toCharArray()){switch(c){case '\\'->out.append("\\\\");case '"'->out.append("\\\"");case '\n'->out.append("\\n");case '\r'->out.append("\\r");case '\t'->out.append("\\t");case '\b'->out.append("\\b");case '\f'->out.append("\\f");default->out.append(c);}}return out.append('"').toString();} private String characterLiteral(char value){return switch(value){case '\n'->"'\\n'";case '\r'->"'\\r'";case '\t'->"'\\t'";case '\b'->"'\\b'";case '\f'->"'\\f'";case '\\'->"'\\\\'";case '\''->"'\\''";case '"'->"'\"'";default->"'"+value+"'";};}
private void expression(StringBuilder b,Expression e){if(e instanceof LiteralExpression x){if(x.value() instanceof String s)b.append(quoteString(s));else if(x.value() instanceof Boolean v)b.append(v?"1":"0");else if(x.value() instanceof Character c)b.append(characterLiteral(c));else { b.append(x.value()); if(x.value() instanceof Long)b.append(cppStyle?"LL":"L"); if(x.value() instanceof Float)b.append("f"); }}else if(e instanceof NameExpression x)b.append(x.name());else if(e instanceof BinaryExpression x){b.append('(');expression(b,x.left());b.append(' ').append(x.operator()).append(' ');expression(b,x.right());b.append(')');}else if(e instanceof ArrayAccessExpression x){expression(b,x.array());b.append('[');expression(b,x.index());b.append(']');}else if(e instanceof AssignmentExpression x){b.append('(');expression(b,x.target());b.append(" = ");expression(b,x.value());b.append(')');}else if(e instanceof UpdateExpression x){b.append('(');if(x.prefix())b.append(x.operator());b.append(x.target().name());if(!x.prefix())b.append(x.operator());b.append(')');}else if(e instanceof UnaryExpression x){b.append('(').append(x.operator());expression(b,x.operand());b.append(')');}else if(e instanceof CallExpression x){if(x.callee().equals("__codebridge_cout")){b.append("std::cout");for(Expression item:x.arguments()){b.append(" << ");if(item instanceof CallExpression endl&&endl.callee().equals("__codebridge_endl"))b.append("std::endl");else expression(b,item);}return;}b.append(x.callee()).append('(');for(int i=0;i<x.arguments().size();i++){if(i>0){b.append(", ");if(x.callee().equals("scanf")&&i>0)b.append((char)38);}expression(b,x.arguments().get(i));}b.append(')');}else throw new UnsupportedOperationException("Unsupported C expression node: "+e.getClass().getSimpleName());}
